1	"use client";
2	
3	import Link from "next/link";
4	import { useEffect, useRef, useState } from "react";
5	import { IconArrow, IconCheck } from "./icons";
6	
7	type Status = "available" | "taken" | "unknown";
8	
9	type Result = {
10	  domain: string;
11	  sld: string;
12	  tld: string;
13	  status: Status;
14	  available: boolean;
15	  premium: boolean;
16	  priceCents: number | null;
17	  renewCents: number | null;
18	};
19	
20	type ApiResponse = {
21	  configured?: boolean;
22	  throttled?: boolean;
23	  query?: string;
24	  exact?: Result | null;
25	  results?: Result[];
26	};
27	
28	type UiStatus = "idle" | "loading" | "results" | "soon" | "auth" | "error";
29	
30	import { POPULAR_TLDS } from "./tlds";
31	export { POPULAR_TLDS };
32	
33	function money(cents: number | null): string {
34	  if (cents == null) return "—";
35	  const v = cents / 100;
36	  return `$${v.toFixed(2)}`;
37	}
38	
39	const transferHref = (domain: string) => `/dashboard/domains/transfer?domain=${encodeURIComponent(domain)}`;
40	const registerHref = (domain: string) => `/register?domain=${encodeURIComponent(domain)}`;
41	
42	export function DomainChecker({ compact = false }: { compact?: boolean }) {
43	  const [q, setQ] = useState("");
44	  const [status, setStatus] = useState<UiStatus>("idle");
45	  const [exact, setExact] = useState<Result | null>(null);
46	  const [results, setResults] = useState<Result[]>([]);
47	  const debounce = useRef<ReturnType<typeof setTimeout> | null>(null);
48	  const abort = useRef<AbortController | null>(null);
49	
50	  useEffect(() => {
51	    const query = q.trim().toLowerCase();
52	    if (debounce.current) clearTimeout(debounce.current);
53	    abort.current?.abort();
54	
55	    if (query.length < 2) {
56	      setStatus("idle");
57	      setExact(null);
58	      setResults([]);
59	      return;
60	    }
61	
62	    setStatus("loading");
63	    debounce.current = setTimeout(async () => {
64	      const ac = new AbortController();
65	      abort.current = ac;
66	      try {
67	        const res = await fetch(`/api/domains/check?q=${encodeURIComponent(query)}`, {
68	          signal: ac.signal,
69	        });
70	        if (res.status === 401) {
71	          setStatus("auth");
72	          return;
73	        }
74	        const data: ApiResponse = await res.json();
75	        if (data.configured === false) {
76	          setStatus("soon");
77	          return;
78	        }
79	        setExact(data.exact ?? null);
80	        setResults(Array.isArray(data.results) ? data.results : []);
81	        setStatus("results");
82	      } catch (e: any) {
83	        if (e?.name === "AbortError") return;
84	        setStatus("error");
85	      }
86	    }, 400);
87	
88	    return () => {
89	      if (debounce.current) clearTimeout(debounce.current);
90	    };
91	  }, [q]);
92	
93	  // Alternatives: available first (cheapest first), then unknown, then taken.
94	  // The exact typed domain is rendered separately as the primary, so drop it here.
95	  const rank: Record<Status, number> = { available: 0, unknown: 1, taken: 2 };
96	  const sorted = results
97	    .filter((r) => !exact || r.domain !== exact.domain)
98	    .sort(
99	    (a, b) =>
100	      rank[a.status] - rank[b.status] ||
101	      (a.priceCents ?? Number.MAX_SAFE_INTEGER) - (b.priceCents ?? Number.MAX_SAFE_INTEGER) ||
102	      a.domain.length - b.domain.length,
103	  );
104	  const availableAlts = sorted.filter((r) => r.status === "available");
105	
106	  return (
107	    <div className="w-full">
108	      <style>{`
109	        .nx-dom-row { animation: nx-dom-in 0.35s cubic-bezier(0.22,1,0.36,1) both; }
110	        @keyframes nx-dom-in { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }
111	        .nx-dot { animation: nx-dot 1s ease-in-out infinite; }
112	        .nx-dot:nth-child(2) { animation-delay: 0.15s; }
113	        .nx-dot:nth-child(3) { animation-delay: 0.3s; }
114	        @keyframes nx-dot { 0%,100% { opacity: 0.25; } 50% { opacity: 1; } }
115	        @media (prefers-reduced-motion: reduce) { .nx-dom-row, .nx-dot { animation: none !important; } }
116	      `}</style>
117	
118	      {/* Search field */}
119	      <div className="group relative">
120	        <div className="pointer-events-none absolute -inset-[1px] rounded-2xl bg-gradient-to-r from-accent-blue/40 via-brand-500/40 to-accent-cyan/40 opacity-0 blur transition-opacity duration-300 group-focus-within:opacity-100" />
121	        <div className="relative flex items-center gap-2 rounded-2xl border border-white/10 bg-navy-900/80 p-2 backdrop-blur-md transition-colors focus-within:border-brand-400/50">
122	          <span className="pl-2 text-slate-500" aria-hidden>
123	            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round">
124	              <circle cx="11" cy="11" r="7" />
125	              <path d="m20 20-3-3" />
126	            </svg>
127	          </span>
128	          <input
129	            value={q}
130	            onChange={(e) => setQ(e.target.value)}
131	            placeholder="Find your perfect domain — try mahaskitchen.in"
132	            spellCheck={false}
133	            autoCapitalize="off"
134	            autoCorrect="off"
135	            className="min-w-0 flex-1 bg-transparent px-1 py-2.5 text-base text-slate-100 outline-none placeholder:text-slate-500"
136	            aria-label="Search for a domain"
137	          />
138	          <span className="hidden shrink-0 items-center gap-2 pr-2 text-xs text-slate-500 sm:flex">
139	            {status === "loading" ? (
140	              <>
141	                <span className="nx-dot h-1.5 w-1.5 rounded-full bg-brand-400" />
142	                <span className="nx-dot h-1.5 w-1.5 rounded-full bg-brand-400" />
143	                <span className="nx-dot h-1.5 w-1.5 rounded-full bg-brand-400" />
144	              </>
145	            ) : (
146	              <span className="rounded-md border border-white/10 bg-white/[0.04] px-2 py-1">
147	                Any extension
148	              </span>
149	            )}
150	          </span>
151	        </div>
152	      </div>
153	
154	      {/* Results / states */}
155	      <div className="mt-4">
156	        {status === "results" && (
157	          <div className="space-y-4">
158	            {/* Exact typed domain — the primary result, whatever its extension */}
159	            {exact && (
160	              <div
161	                className={`nx-dom-row rounded-xl border p-4 backdrop-blur-md ${
162	                  exact.status === "available"
163	                    ? "border-emerald-500/25 bg-emerald-500/[0.05]"
164	                    : exact.status === "taken"
165	                      ? "border-white/10 bg-navy-900/70"
166	                      : "border-amber-400/25 bg-amber-400/[0.05]"
167	                }`}
168	              >
169	                <div className="flex flex-wrap items-center gap-3">
170	                  <span
171	                    className={`flex h-7 w-7 items-center justify-center rounded-full ${
172	                      exact.status === "available"
173	                        ? "bg-emerald-500/15 text-emerald-400"
174	                        : "bg-slate-500/15 text-slate-400"
175	                    }`}
176	                  >
177	                    {exact.status === "available" ? (
178	                      <IconCheck size={14} />
179	                    ) : (
180	                      <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
181	                        <path d="M6 6l12 12M18 6 6 18" />
182	                      </svg>
183	                    )}
184	                  </span>
185	                  <span className="min-w-0 break-all font-mono text-base font-semibold text-white">{exact.domain}</span>
186	                  {exact.premium && (
187	                    <span className="rounded-full border border-amber-400/30 bg-amber-400/10 px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide text-amber-300">
188	                      Premium
189	                    </span>
190	                  )}
191	                  {exact.status === "available" ? (
192	                    <span className="ml-auto flex items-center gap-3">
193	                      <span className="text-right text-sm">
194	                        <span className="font-semibold text-white">{money(exact.priceCents)}</span>
195	                        <span className="text-slate-500">/yr</span>
196	                      </span>
197	                      <Link href={registerHref(exact.domain)} className="btn-primary px-3.5 py-1.5 text-xs">
198	                        Register
199	                        <IconArrow size={13} />
200	                      </Link>
201	                    </span>
202	                  ) : exact.status === "taken" ? (
203	                    <span className="ml-auto rounded-full border border-white/10 bg-white/[0.05] px-2.5 py-1 text-xs font-medium text-slate-300">
204	                      Taken
205	                    </span>
206	                  ) : (
207	                    <span className="ml-auto text-xs text-amber-300/90">Couldn&apos;t verify</span>
208	                  )}
209	                </div>
210	                {exact.status === "taken" && (
211	                  <p className="mt-3 text-xs leading-relaxed text-slate-400">
212	                    <b className="text-slate-300">{exact.domain}</b> is already registered.{" "}
213	                    <Link href={transferHref(exact.domain)} className="text-brand-300 hover:text-brand-200">
214	                      Transfer it in
215	                    </Link>{" "}
216	                    if it&apos;s yours, or pick one of the available extensions below.
217	                  </p>
218	                )}
219	              </div>
220	            )}
221	
222	            {/* Alternative extensions */}
223	            {sorted.length > 0 && (
224	              <div>
225	                {exact && (
226	                  <p className="mb-2 text-xs font-medium uppercase tracking-wider text-slate-500">
227	                    {exact.status === "available" ? "More extensions" : "Available alternatives"}
228	                  </p>
229	                )}
230	                <ul className="space-y-2">
231	                  {sorted.map((r, i) => (
232	                    <li
233	                      key={r.domain}
234	                      className="nx-dom-row flex flex-wrap items-center gap-3 rounded-xl border border-white/[0.07] bg-navy-900/60 px-4 py-3 backdrop-blur-md transition-colors hover:border-brand-500/30"
235	                      style={{ animationDelay: `${Math.min(i, 10) * 35}ms` }}
236	                    >
237	                      <span
238	                        className={`flex h-7 w-7 items-center justify-center rounded-full ${
239	                          r.status === "available" ? "bg-emerald-500/15 text-emerald-400" : "bg-slate-500/15 text-slate-500"
240	                        }`}
241	                      >
242	                        {r.status === "available" ? (
243	                          <IconCheck size={14} />
244	                        ) : (
245	                          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
246	                            <path d="M6 6l12 12M18 6 6 18" />
247	                          </svg>
248	                        )}
249	                      </span>
250	                      <span className="font-mono text-sm font-medium text-white">{r.domain}</span>
251	                      {r.premium && (
252	                        <span className="rounded-full border border-amber-400/30 bg-amber-400/10 px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide text-amber-300">
253	                          Premium
254	                        </span>
255	                      )}
256	                      <span className="ml-auto flex items-center gap-3">
257	                        {r.status === "available" ? (
258	                          <>
259	                            <span className="text-right text-sm">
260	                              <span className="font-semibold text-white">{money(r.priceCents)}</span>
261	                              <span className="text-slate-500">/yr</span>
262	                            </span>
263	                            <Link href={registerHref(r.domain)} className="btn-primary px-3.5 py-1.5 text-xs">
264	                              Register
265	                              <IconArrow size={13} />
266	                            </Link>
267	                          </>
268	                        ) : r.status === "taken" ? (
269	                          <span className="text-xs text-slate-500">Taken</span>
270	                        ) : (
271	                          <span className="text-xs text-amber-300/80">Couldn&apos;t verify</span>
272	                        )}
273	                      </span>
274	                    </li>
275	                  ))}
276	                </ul>
277	              </div>
278	            )}
279	
280	            {!exact && availableAlts.length === 0 && sorted.length > 0 && (
281	              <p className="rounded-xl border border-white/[0.07] bg-navy-900/60 px-4 py-3 text-sm text-slate-400">
282	                Every extension for that name is taken — try a different name.
283	              </p>
284	            )}
285	
286	            {!exact && sorted.length === 0 && (
287	              <p className="rounded-xl border border-white/[0.07] bg-navy-900/60 px-4 py-3 text-sm text-slate-400">
288	                No matches for that query — try a different name.
289	              </p>
290	            )}
291	          </div>
292	        )}
293	
294	        {status === "auth" && (
295	          <div className="rounded-xl border border-brand-500/25 bg-brand-500/[0.06] px-4 py-3 text-sm text-slate-300">
296	            <b className="text-white">Live availability is one step away.</b>{" "}
297	            <Link href="/register" className="text-brand-300 hover:underline">
298	              Create a free account
299	            </Link>{" "}
300	            to search and register domains in real time — then point them at your VPS in a click.
301	          </div>
302	        )}
303	
304	        {status === "soon" && (
305	          <div className="rounded-xl border border-amber-400/25 bg-amber-400/[0.06] px-4 py-3 text-sm text-amber-200/90">
306	            <b>Domain registration is launching soon.</b> Prices below are indicative starting
307	            rates — check back shortly to register live.
308	          </div>
309	        )}
310	
311	        {status === "error" && (
312	          <p className="rounded-xl border border-red-500/25 bg-red-500/[0.06] px-4 py-3 text-sm text-red-300">
313	            Something went wrong checking that domain. Please try again.
314	          </p>
315	        )}
316	      </div>
317	
318	      {/* Popular TLD chips */}
