/**
 * PREVIEW-ONLY sample data for the Domains landing template direction
 * (components/marketing/domainstemplate/*). Nothing here touches the live
 * /domains page or the real DomainChecker API — it exists purely so the
 * /preview/domains route renders with realistic, honest content.
 *
 * Reviews are ILLUSTRATIVE sample content (same status as the existing
 * <Testimonials/>), kept modest and honest — no fabricated counts.
 */

export type DomainReview = {
  id: string;
  quote: string;
  name: string;
  meta: string;
};

/** A registrable extension shown in the hero result grid + pricing rail. */
export type TldRow = {
  tld: string;
  /** Display price string, e.g. "$10.99". */
  price: string;
  /** Small note, e.g. "most popular" / "great for tech". */
  note?: string;
  hot?: boolean;
};

/** The auto-typed demo brand name in the hero search. */
export const DEMO_QUERY = "mahaskitchen";

/** Extensions the hero demo "checks" the demo name against (with prices). */
export const DEMO_TLDS: { tld: string; price: string; available: boolean; premium?: boolean }[] = [
  { tld: ".com", price: "$10.99", available: true },
  { tld: ".in", price: "$8.99", available: true },
  { tld: ".co", price: "$24.99", available: true },
  { tld: ".shop", price: "$3.49", available: true, premium: false },
  { tld: ".io", price: "$34.99", available: false },
  { tld: ".net", price: "$12.99", available: true },
];

export const PRICING_TLDS: TldRow[] = [
  { tld: ".com", price: "$10.99", note: "The one people trust", hot: true },
  { tld: ".io", price: "$34.99", note: "Loved by tech + startups" },
  { tld: ".ai", price: "$69.99", note: "For anything AI" },
  { tld: ".dev", price: "$14.99", note: "Built-in HTTPS" },
  { tld: ".shop", price: "$3.49", note: "Sell online" },
  { tld: ".co", price: "$24.99", note: "Short + brandable" },
  { tld: ".xyz", price: "$2.99", note: "Cheapest to start" },
  { tld: ".in", price: "$8.99", note: "India" },
];

export const DOMAIN_REVIEWS: DomainReview[] = [
  {
    id: "d1",
    quote:
      "Grabbed the .com and pointed it at my VPS from the same dashboard — no glue records, no waiting a day for DNS. It just worked.",
    name: "Aran D.",
    meta: "Founder",
  },
  {
    id: "d2",
    quote:
      "Transferred three domains in and moved my email over the same afternoon. Having domain, hosting and mailboxes on one bill is the whole reason I stayed.",
    name: "Priya S.",
    meta: "Agency owner",
  },
  {
    id: "d3",
    quote:
      "DNS changes propagate in seconds and the record editor is actually readable. I stopped dreading the registrar panel.",
    name: "Marcus L.",
    meta: "Indie developer",
  },
];

export const RATING_AVG = "4.9";
export const RATING_LABEL = "Rated by people who own their names here";

/* Scoped motion for the /preview/domains template. Net-new, additive, and every
   animation is disabled under prefers-reduced-motion. Global pv-* and animate-*
   keyframes are reused where they already exist; only genuinely new motion lives
   here. */

/* "checking…" bouncing dots in the search field */
.dots > span {
  animation: nxDomDot 1s ease-in-out infinite;
}
.dots > span:nth-child(2) {
  animation-delay: 0.15s;
}
.dots > span:nth-child(3) {
  animation-delay: 0.3s;
}
@keyframes nxDomDot {
  0%,
  100% {
    opacity: 0.25;
    transform: translateY(0);
  }
  50% {
    opacity: 1;
    transform: translateY(-2px);
  }
}

/* the "available" badge / primary result pops in */
.pop {
  animation: nxDomPop 0.42s cubic-bezier(0.22, 1, 0.36, 1) both;
}
@keyframes nxDomPop {
  from {
    opacity: 0;
    transform: scale(0.82);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

/* a slim scanning line that sweeps the search panel while it "checks" */
.scanline {
  animation: nxDomScan 1s ease-in-out infinite;
}
@keyframes nxDomScan {
  0% {
    transform: translateY(0);
    opacity: 0;
  }
  20%,
  80% {
    opacity: 0.9;
  }
  100% {
    transform: translateY(120px);
    opacity: 0;
  }
}

/* result rows stagger in (used with inline animation-delay) */
.row {
  animation: nxDomRow 0.4s cubic-bezier(0.22, 1, 0.36, 1) both;
}
@keyframes nxDomRow {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* the account-bundle connective spine draws down once in view */
.spine {
  transform-origin: top;
  animation: nxDomSpine 0.9s cubic-bezier(0.22, 1, 0.36, 1) both;
}
@keyframes nxDomSpine {
  from {
    transform: scaleY(0);
  }
  to {
    transform: scaleY(1);
  }
}

@media (prefers-reduced-motion: reduce) {
  .dots > span,
  .pop,
  .scanline,
  .row,
  .spine {
    animation: none !important;
    transform: none !important;
    opacity: 1 !important;
  }
}

"use client";

/**
 * PREVIEW TEMPLATE — Domains landing (Direction: "Register + transfer").
 *
 * Hero centerpiece = an animated domain-search widget in a premium glass frame:
 * it auto-types a brandable name, runs a "checking" scan, then reveals the exact
 * result plus a TLD price grid that populates row-by-row. The visitor can also
 * type their own name and get an instant (mocked) availability read — so the hero
 * doubles as a working-looking search, which is the whole buying trigger.
 *
 * Below the hero: the "everything in one account" bundling story (domain +
 * hosting + email on one bill), a transfer + managed-DNS section that reuses the
 * real <DnsManager/> showcase screen, a TLD pricing rail, and compact 5-star
 * reviews. Asymmetric/editorial throughout — never a centered stack.
 *
 * Net-new, preview-only. Touches no live page or shared component (imports the
 * shared DnsManager + gamelanding kit read-only; reuse, not edits).
 */

import Link from "next/link";
import { useEffect, useMemo, useState } from "react";
import styles from "./domains.module.css";
import {
  DEMO_QUERY,
  DEMO_TLDS,
  PRICING_TLDS,
  DOMAIN_REVIEWS,
  RATING_AVG,
  RATING_LABEL,
} from "./data";
import { POPULAR_TLDS } from "@/components/marketing/tlds";
import { DnsManager } from "@/components/marketing/showcase/DnsManager";
import { usePrefersReducedMotion, useInViewOnce, StarRow } from "@/components/marketing/gamelanding/kit";
import {
  IconArrow,
  IconCheck,
  IconGlobe,
  IconMail,
  IconServer,
  IconLock,
  IconBolt,
  IconShield,
  IconNetwork,
  IconClock,
} from "@/components/marketing/icons";

type Phase = "typing" | "checking" | "results";
type Mode = "demo" | "user";
type ResultRow = { domain: string; tld: string; available: boolean; price: string; premium?: boolean };

function money(cents: number): string {
  return `$${(cents / 100).toFixed(2)}`;
}

/** Deterministic pseudo-availability so user-typed names read realistically. */
function avail(name: string, tld: string): boolean {
  let h = 5381;
  const s = `${name.toLowerCase()}.${tld}`;
  for (let i = 0; i < s.length; i++) h = ((h << 5) + h + s.charCodeAt(i)) >>> 0;
  return h % 4 !== 0; // ~75% available
}

function buildResults(name: string, mode: Mode): { exact: ResultRow; rows: ResultRow[] } {
  if (mode === "demo") {
    const rows: ResultRow[] = DEMO_TLDS.map((t) => ({
      domain: `${name}${t.tld}`,
      tld: t.tld,
      available: t.available,
      price: t.price,
      premium: t.premium,
    }));
    return { exact: rows[0], rows: rows.slice(1) };
  }
  const rows: ResultRow[] = POPULAR_TLDS.slice(0, 6).map((t) => ({
    domain: `${name}${t.tld}`,
    tld: t.tld,
    available: avail(name, t.tld.replace(/^\./, "")),
    price: money(t.fromCents),
  }));
  const exact = rows.find((r) => r.tld === ".com") ?? rows[0];
  return { exact, rows: rows.filter((r) => r !== exact) };
}

/* ── The animated search widget (hero centerpiece) ───────────────────────── */
function DomainSearchPanel() {
  const reduced = usePrefersReducedMotion();
  const [q, setQ] = useState("");
  const [phase, setPhase] = useState<Phase>("typing");
  const [mode, setMode] = useState<Mode>("demo");

  // Auto-demo loop (only while untouched). Reduced motion → rest on the result state.
  useEffect(() => {
    if (mode !== "demo") return;
    if (reduced) {
      setQ(DEMO_QUERY);
      setPhase("results");
      return;
    }
    let cancelled = false;
    const timers: ReturnType<typeof setTimeout>[] = [];
    const run = () => {
      if (cancelled) return;
      setQ("");
      setPhase("typing");
      let i = 0;
      const typeNext = () => {
        if (cancelled) return;
        i += 1;
        setQ(DEMO_QUERY.slice(0, i));
        if (i < DEMO_QUERY.length) {
          timers.push(setTimeout(typeNext, 78));
        } else {
          setPhase("checking");
          timers.push(
            setTimeout(() => {
              if (cancelled) return;
              setPhase("results");
              timers.push(setTimeout(() => run(), 4200));
            }, 950),
          );
        }
      };
      timers.push(setTimeout(typeNext, 650));
    };
    run();
    return () => {
      cancelled = true;
      timers.forEach(clearTimeout);
    };
  }, [mode, reduced]);

  // User-mode: brief "checking" then results.
  useEffect(() => {
    if (mode !== "user") return;
    if (q.trim().length < 2) {
      setPhase("typing");
      return;
    }
    setPhase("checking");
    const t = setTimeout(() => setPhase("results"), 480);
    return () => clearTimeout(t);
  }, [q, mode]);

  const name = (q.trim().toLowerCase() || DEMO_QUERY).replace(/\s+/g, "");
  const { exact, rows } = useMemo(() => buildResults(name, mode), [name, mode]);
  const showResults = phase === "results" && (mode === "demo" || q.trim().length >= 2);

  return (
    <div className="relative">
      {/* focus glow ring */}
