/* Scoped motion for the /preview/nxcloud template. Net-new, additive. Every
   animation is disabled under prefers-reduced-motion. Global pv-* / animate-*
   keyframes are reused where they already exist; only new motion lives here. */

/* Talk waveform bars */
.bar {
  transform-origin: center;
  animation: nxCloudBar 1.1s ease-in-out infinite;
}
@keyframes nxCloudBar {
  0%,
  100% {
    transform: scaleY(0.35);
  }
  50% {
    transform: scaleY(1);
  }
}

/* a gently rotating sync glyph */
.spin {
  animation: nxCloudSpin 2.4s linear infinite;
}
@keyframes nxCloudSpin {
  to {
    transform: rotate(360deg);
  }
}

/* file/feature rows stagger in (used with inline animation-delay) */
.row {
  animation: nxCloudRow 0.45s cubic-bezier(0.22, 1, 0.36, 1) both;
}
@keyframes nxCloudRow {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* the collaborator caret blink in the Office mock */
.caret {
  animation: nxCloudCaret 1.1s steps(1) infinite;
}
@keyframes nxCloudCaret {
  0%,
  50% {
    opacity: 1;
  }
  50.01%,
  100% {
    opacity: 0;
  }
}

@media (prefers-reduced-motion: reduce) {
  .bar,
  .spin,
  .row,
  .caret {
    animation: none !important;
    transform: none !important;
    opacity: 1 !important;
  }
}

