/* ── Hero Files dashboard (the centerpiece) ──────────────────────────────── */
function FilesPanel() {
  const reduced = usePrefersReducedMotion();
  const [pct, setPct] = useState(reduced ? 100 : 0);
  const [synced, setSynced] = useState(reduced);

  useEffect(() => {
    if (reduced) return;
    let p = 0;
    let phase: "up" | "hold" | "reset" = "up";
    let hold = 0;
    const id = window.setInterval(() => {
      if (document.hidden) return;
      if (phase === "up") {
        p = Math.min(100, p + 6);
        setPct(p);
        if (p >= 100) {
          setSynced(true);
          phase = "hold";
          hold = 0;
        }
      } else if (phase === "hold") {
        hold += 1;
        if (hold > 22) phase = "reset";
      } else {
        p = 0;
        setPct(0);
        setSynced(false);
        phase = "up";
      }
    }, 95);
    return () => window.clearInterval(id);
  }, [reduced]);

  return (
    <div className="relative">
      <div
        className="pointer-events-none absolute -inset-[1.5px] rounded-[26px] bg-gradient-to-r from-accent-blue/40 via-brand-500/40 to-accent-cyan/40 opacity-70 blur-lg"
        aria-hidden
      />
      <div className="relative overflow-hidden rounded-3xl border border-white/10 bg-[#080d18]/90 shadow-2xl shadow-black/50 backdrop-blur-xl">
        <div
          className="pointer-events-none absolute -inset-16 -z-10 opacity-70"
          style={{ background: "radial-gradient(45% 45% at 85% 0%, rgba(138,112,251,0.20), transparent 70%)" }}
          aria-hidden
