        {/* header */}
        <div className="flex items-center gap-2.5 border-b border-white/[0.06] bg-white/[0.02] px-4 py-3">
          <span className="flex h-7 w-7 items-center justify-center rounded-lg bg-gradient-to-br from-accent-blue to-brand-500 text-white">
            <CloudGlyph size={15} />
          </span>
          <span className="text-[13px] font-semibold text-white">NxCloud</span>
          <span className="text-[12px] text-slate-500">/ Files</span>
          <span className="ml-auto flex items-center -space-x-1.5">
            <Avatar initial="L" />
            <Avatar initial="S" />
            <Avatar initial="D" />
            <span className="ml-2.5 text-[11px] text-slate-500">+4</span>
          </span>
        </div>

        <div className="p-4 sm:p-5">
          {/* storage meter */}
          <div className="mb-4 rounded-xl border border-white/[0.06] bg-white/[0.02] px-3.5 py-3">
            <div className="flex items-center justify-between text-[12px]">
              <span className="inline-flex items-center gap-2 text-slate-300">
                <IconDisk size={14} />
                Storage
              </span>
              <span className="font-mono text-slate-400">
                <span className="font-semibold text-white">612 GB</span> of 2 TB
              </span>
            </div>
            <div className="mt-2">
              <UsageBar pct={30} className="h-1.5" />
            </div>
          </div>

          {/* file list */}
          <ul className="space-y-1.5">
            {HERO_FILES.map((f, i) => (
              <li
                key={f.name}
                className={`${styles.row} flex items-center gap-3 rounded-xl border border-white/[0.06] bg-white/[0.02] px-3 py-2.5`}
                style={{ animationDelay: `${100 + i * 80}ms` }}
              >
                <span className={`flex h-9 w-9 shrink-0 items-center justify-center rounded-lg bg-gradient-to-br text-[10px] font-bold ${f.tint}`}>
                  {f.kind}
                </span>
                <div className="min-w-0 flex-1">
                  <p className="truncate text-[13px] font-medium text-white">{f.name}</p>
                  {f.active && !synced ? (
                    <div className="mt-1.5 max-w-[180px]">
                      <div className="h-1 w-full overflow-hidden rounded-full bg-white/[0.08]">
                        <div
                          className="h-full rounded-full bg-gradient-to-r from-accent-cyan to-brand-400 transition-[width] duration-100"
