                      </div>
                    </div>
                  ) : (
                    <p className="truncate text-[11px] text-slate-500">{f.size}</p>
                  )}
                </div>
                {f.active ? (
                  synced ? (
                    <span className="inline-flex shrink-0 items-center gap-1.5 rounded-full bg-emerald-500/12 px-2 py-0.5 text-[10px] font-medium text-emerald-300">
                      <IconCheck size={11} />
