}
@keyframes nxToolScan {
  0% {
    transform: translateY(0);
    opacity: 0;
  }
  15%,
  85% {
    opacity: 0.9;
  }
  100% {
    transform: translateY(var(--nx-scan, 160px));
    opacity: 0;
  }
}

/* result panel reveals */
.reveal {
  animation: nxToolReveal 0.5s cubic-bezier(0.22, 1, 0.36, 1) both;
