    opacity: 1;
    transform: translateY(0);
  }
}

/* staggered detail rows */
.row {
  animation: nxToolRow 0.4s cubic-bezier(0.22, 1, 0.36, 1) both;
}
@keyframes nxToolRow {
  from {
    opacity: 0;
    transform: translateY(6px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* pinging dots */
.dots > span {
  animation: nxToolDot 1s ease-in-out infinite;
