  const [result, setResult] = useState<MockResult | null>(reduced ? buildMock("play.example.net", 25565) : null);
  const [runId, setRunId] = useState(0);

  function run(h: string, p: string) {
    const portNum = p.trim() ? Number(p) : 25565;
    if (reduced) {
      setResult(buildMock(h, portNum));
      setStatus("done");
      setRunId((n) => n + 1);
      return;
    }
    setStatus("pinging");
    setResult(null);
    const t = setTimeout(() => {
      setResult(buildMock(h, portNum));
      setStatus("done");
      setRunId((n) => n + 1);
    }, 950);
    return () => clearTimeout(t);
