                  <KVLatency history={result.history} latency={result.latency} reduced={reduced} delay={180} />
                  <KV icon={<IconNetwork size={14} />} k="Edition" v="Java · SRV followed" delay={240} />
                </div>

                {/* online-now chips */}
                <div className="mt-3">
                  <p className="mb-1.5 text-[11px] font-medium uppercase tracking-wider text-slate-500">Online now</p>
                  <div className="flex flex-wrap gap-1.5">
