function KV({ icon, k, v, delay }: { icon: React.ReactNode; k: string; v: string; delay: number }) {
  return (
    <div className={`flex items-center gap-2.5 rounded-xl border border-white/[0.06] bg-white/[0.02] px-3 py-2.5 ${styles.row}`} style={{ animationDelay: `${delay}ms` }}>
      <span className="text-brand-300">{icon}</span>
      <div className="min-w-0">
        <p className="text-[10px] uppercase tracking-wide text-slate-500">{k}</p>
        <p className="truncate font-mono text-[13px] text-white">{v}</p>
      </div>
    </div>
  );
}

function KVLatency({ history, latency, reduced, delay }: { history: number[]; latency: number; reduced: boolean; delay: number }) {
  const maxV = Math.max(...history, 1);
  return (
    <div className={`flex items-center gap-2.5 rounded-xl border border-white/[0.06] bg-white/[0.02] px-3 py-2.5 ${styles.row}`} style={{ animationDelay: `${delay}ms` }}>
      <span className="text-brand-300">
        <IconGauge size={14} />
      </span>
      <div className="min-w-0 flex-1">
        <p className="text-[10px] uppercase tracking-wide text-slate-500">Latency</p>
        <div className="flex items-center gap-2">
          <p className="font-mono text-[13px] text-white">{latency} ms</p>
          <span className="flex h-4 flex-1 items-end gap-[2px]">
            {history.map((v, i) => (
              <span
                key={i}
                className={`w-full origin-bottom rounded-[1px] bg-gradient-to-t from-brand-500 to-accent-cyan ${reduced ? "" : "motion-safe:animate-grow-up"}`}
                style={{ height: `${Math.max(15, (v / maxV) * 100)}%`, animationDelay: `${i * 40}ms` }}
              />
            ))}
          </span>
        </div>
      </div>
    </div>
  );
}

