              <span className="eyebrow">Want your own?</span>
              <h2 className="mt-2 text-2xl font-bold tracking-tight text-white sm:text-3xl">
                Spin up your Minecraft server in under a minute
              </h2>
              <p className="mt-3 max-w-xl text-[15px] leading-relaxed text-slate-300">
                High-clock NVMe boxes, a dedicated IP, one-click modpacks and DDoS protection — deployed instantly, then
                run from a clean panel. Your server address for this checker is 47 seconds away.
              </p>
              <div className="mt-5 flex flex-wrap items-center gap-4">
                <StarRow rating={5} />
                <span className="text-sm text-slate-400">Loved by server owners</span>
              </div>
            </div>
            <div className="flex flex-col gap-3 lg:col-span-4 lg:items-end">
              <Link href="/minecraft-server-hosting" className="btn-deploy w-full px-6 py-3 text-center text-base lg:w-auto">
                Deploy a Minecraft server
                <span className="dep-arrow" aria-hidden>→</span>
              </Link>
              <Link href="/game-servers" className="btn-secondary w-full px-5 py-3 text-center text-base lg:w-auto">
                All game servers
              </Link>
            </div>
          </div>
        </div>
      </section>

      {/* ── HOW IT WORKS ─────────────────────────────────────────────────── */}
      <section className="tone-panel py-16">
        <div className="rail">
          <div className="max-w-2xl">
            <span className="eyebrow">How it works</span>
            <h2 className="mt-3 text-2xl font-bold tracking-tight text-white sm:text-3xl">Three steps, no install</h2>
          </div>
          <ol className="mt-9 grid gap-4 md:grid-cols-3">
            {HOW_STEPS.map((s, i) => (
              <li key={s.title} className="card flex flex-col">
                <span className="flex h-8 w-8 items-center justify-center rounded-full border border-brand-500/30 bg-brand-500/10 text-sm font-semibold text-brand-200">
                  {i + 1}
                </span>
                <h3 className="mt-4 text-base font-semibold text-white">{s.title}</h3>
                <p className="mt-2 text-sm leading-relaxed text-slate-400">{s.body}</p>
              </li>
            ))}
          </ol>
        </div>
      </section>

      {/* ── RELATED TOOLS ────────────────────────────────────────────────── */}
      <section className="rail py-16">
        <div className="flex flex-wrap items-end justify-between gap-4">
          <div className="max-w-xl">
            <span className="eyebrow">More free tools</span>
            <h2 className="mt-3 text-2xl font-bold tracking-tight text-white sm:text-3xl">While you&apos;re here</h2>
          </div>
          <Link href="/tools" className="text-sm font-semibold text-brand-300 hover:text-brand-200">
            All tools →
          </Link>
        </div>
        <div className="mt-8 grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
          {RELATED_TOOLS.map((t) => (
            <Link key={t.href} href={t.href} className="card card-hover group flex items-start gap-3">
              <span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-lg border border-white/10 bg-white/[0.03] font-mono text-[10px] font-bold text-brand-200">
                {t.badge}
              </span>
              <div className="min-w-0 flex-1">
                <p className="flex items-center justify-between gap-2 text-sm font-semibold text-white">
                  {t.label}
                  <span className="text-slate-600 transition-colors group-hover:text-brand-300">
                    <IconArrow size={14} />
                  </span>
                </p>
                <p className="mt-1 text-[13px] leading-relaxed text-slate-400">{t.desc}</p>
              </div>
            </Link>
          ))}
        </div>
      </section>

      {/* ── REVIEWS / TRUST ──────────────────────────────────────────────── */}
      <section className="tone-deep pb-24 pt-4">
        <div className="rail grid items-center gap-8 lg:grid-cols-12">
          <div className="lg:col-span-5">
            <div className="flex items-center gap-3">
              <StarRow rating={5} size="text-base" />
              <span className="text-sm text-slate-400">Trusted by players &amp; admins</span>
            </div>
            <h2 className="mt-4 text-2xl font-bold tracking-tight text-white sm:text-3xl">
              A tiny tool people keep bookmarked
            </h2>
            <p className="mt-3 max-w-md text-[15px] leading-relaxed text-slate-400">
              Fast, honest, and free — the kind of utility you reach for before telling the crew it&apos;s up.
            </p>
          </div>
          <div className="grid gap-4 sm:grid-cols-2 lg:col-span-7">
            {TOOL_REVIEWS.map((rv) => (
              <figure key={rv.id} className="card flex flex-col">
                <StarRow rating={5} />
                <blockquote className="mt-3 flex-1 text-sm leading-relaxed text-slate-300">&ldquo;{rv.quote}&rdquo;</blockquote>
                <figcaption className="mt-4 flex items-center gap-2.5 border-t border-white/[0.06] pt-3">
                  <span className="flex h-8 w-8 items-center justify-center rounded-full bg-gradient-to-br from-accent-blue to-brand-500 text-xs font-semibold text-white">
                    {rv.name.charAt(0)}
                  </span>
                  <span className="text-xs">
                    <span className="block font-semibold text-white">{rv.name}</span>
                    <span className="block text-slate-500">{rv.meta}</span>
                  </span>
                </figcaption>
              </figure>
            ))}
          </div>
        </div>
      </section>
    </div>
  );
}

